8|/**
9| * MARK: isAutoResumableWithReason
10| * @description Reasoned form of the Rule 0 auto-resume policy. Agent/CI/
11| *   script stages are safe to re-dispatch — including a ci stage whose
12| *   command happens to run the deploy script, which is an ordinary ci
13| *   stage; merge stages qualify ONLY when a rehydration marker proves the
14| *   attempt is resumable-or-reconcilable (see `hasRehydrationMarkers`) —
15| *   otherwise the exclusion reason names the missing evidence. Tasks with
16| *   an escalated Runner-death streak (`runner-death-loop`) are parked for
17| *   the operator instead of re-dispatched. Every
18| *   exclusion carries its reason so startup recovery can record WHY a task
19| *   stayed parked instead of leaving a silent `interrupted`.
20| * @param {Object} task
21| * @param {Object} stage - Resolved current stage (may be null when unknown).
22| * @param {Object} [opts]
23| * @param {boolean} [opts.blocked] - Whether the task is currently blocked.
24| * @param {boolean} [opts.tripped] - Whether the engine circuit breaker is tripped.
25| * @returns {{ resumable: boolean, reason: string }}
26| * @example isAutoResumableWithReason({ status: "interrupted" }, { type: "agent" }) => { resumable: true, reason: "automated-stage" }
27| ***/
28|export function isAutoResumableWithReason(task, stage, { blocked = false, tripped = false } = {}) {
29|	if (!task || typeof task !== "object") {
30|		return { resumable: false, reason: "unknown-task" };
31|	}
32|	if (task.status === "waiting_human") {
33|		return { resumable: false, reason: "waiting-human" };
34|	}
35|	if (task.status === "paused") {
36|		return { resumable: false, reason: "task-paused" };
37|	}
38|	if (task.status !== "interrupted") {
39|		return { resumable: false, reason: "not-interrupted" };
40|	}
41|	if (blocked) return { resumable: false, reason: "blocked" };
42|	if (tripped) return { resumable: false, reason: "engine-tripped" };
43|	if (hasContinuityHold(task)) return { resumable: false, reason: "continuity-hold" };
44|	// Runner-death loop guard (G7 bound, enforced): the ledger counts
45|	// consecutive Runner deaths per task+stage and escalates at
46|	// MAX_RUNNER_INTERRUPTS — a death streak that long means re-dispatch
47|	// is feeding the loop (e.g. a deploy stage that restarts its own
48|	// Runner). Park for the operator instead of auto-resuming; a human
49|	// resume is unaffected. The ledger resets the count on every stage
50|	// change and clears it on completion, so a count at/over the bound
51|	// always belongs to the stage being resumed.
52|	if (
53|		Number.isInteger(task.runnerInterruptCount) &&
54|		task.runnerInterruptCount >= MAX_RUNNER_INTERRUPTS
55|	) {
56|		return { resumable: false, reason: "runner-death-loop" };
57|	}
58|	if (!stage) return { resumable: false, reason: "unknown-stage" };
59|	if (stage?.paused === true) return { resumable: false, reason: "stage-paused" };
60|	// Normalized: legacy `script` reads as `ci`, `review` as `human`.
61|	const stageType = normalizeStageType(stage?.type);
62|	if (stageType === "agent" || stageType === "ci") {
63|		return { resumable: true, reason: "automated-stage" };
64|	}
65|	if (stageType === "human") {
66|		return { resumable: false, reason: "human-stage" };
67|	}
68|	if (stageType === "merge") {
69|		if (hasRehydrationMarkers(task)) {
70|			return { resumable: true, reason: `rehydratable-${stageType}` };
71|		}
72|		return { resumable: false, reason: "no-rehydration-markers" };
73|	}
74|	return { resumable: false, reason: "unsupported-stage-type" };
