7|/***
8| * MARK: isSchedulerRunnable
9| * @description Single shared predicate for "may the scheduler dispatch this
10| *   task right now". An `in_stage` task needs an automated, unpaused stage
11| *   and no blockers; an `interrupted` task additionally needs the
12| *   `isAutoResumable` policy (merge/human/paused/blocked interruptions stay
13| *   parked for the operator or the continuity plugin); and a task parked
14| *   after consecutive deterministic git failures (`isGitFailureParked`)
15| *   stays unrunnable until an operator retries, resumes, or moves it. The
16| *   `allowInterrupted` flag keeps existing in_stage-only call sites on their
17| *   exact current behaviour until they opt into resume pickup.
18| * @param {Object} task
19| * @param {Object} stage - Resolved current stage.
20| * @param {Object} [opts]
21| * @param {boolean} [opts.blocked] - Whether the task is currently blocked.
22| * @param {boolean} [opts.allowInterrupted] - Whether `interrupted` tasks may qualify.
23| * @param {boolean} [opts.claimed] - Whether a Runner holds a live lease:
24| *   claimed tasks run out-of-process, so the scheduler must not dispatch
25| *   the embedded engine at them (D1 — one holder, one runner).
26| * @returns {boolean}
27| * @example isSchedulerRunnable({ status: "in_stage" }, { type: "agent" }) => true
28| ***/
29|export function isSchedulerRunnable(
30|	task,
31|	stage,
32|	{ blocked = false, allowInterrupted = false, claimed = false } = {},
33|) {
34|	if (!task || !stage) return false;
35|	if (blocked) return false;
36|	if (claimed) return false;
37|	// Git-failure parking: three consecutive deterministic commit/hook
38|	// failures pause auto-dispatch (embedded and Runner scans share this
39|	// gate) until the operator acts — re-running the poisoned tree is
40|	// provably futile.
41|	if (isGitFailureParked(task)) return false;
42|	if (task.status === "interrupted") {
43|		if (!allowInterrupted) return false;
44|		if (!isAutoResumable(task, stage, { blocked })) return false;
45|	} else if (task.status !== "in_stage") {
46|		return false;
47|	}
48|	// Normalized: legacy `script` reads as `ci`.
49|	const stageType = normalizeStageType(stage?.type);
50|	const isAutomated =
51|		stageType === "agent" ||
52|		stageType === "ci" ||
53|		stageType === "merge";
54|	if (!isAutomated || stage?.paused === true) return false;
55|	return true;
56|}

