4|/***
5| * MARK: sortCentralQueue
6| * @description Sorts queue candidates into central dispatch order using the
7| *   shared comparator and policy. This is THE seam both dispatch paths
8| *   (embedded scheduler, runner fleet scan) and the queue display sort
9| *   through. Returns a new array; the input is not mutated. Explicit opts
10| *   (`order`, `maxWaitMs`, `now`) override config; omitted opts resolve from
11| *   the loaded config, so production callers can pass nothing.
12| * @param {Array<Object>} candidates - Candidates with enteredStageAt/stageIndex/totalStages.
13| * @param {Object} [opts] - Passed to `resolveCentralQueuePolicy`.
14| * @returns {Array<Object>} New array in dispatch order.
15| * @example sortCentralQueue([{ enteredStageAt: 2, stageIndex: 1, totalStages: 2 }, { enteredStageAt: 1, stageIndex: 0, totalStages: 3 }]) => [{ enteredStageAt: 1, … }, …]
16| ***/
17|export function sortCentralQueue(candidates, opts = {}) {
18|	const policy = resolveCentralQueuePolicy(opts);
19|	const list = Array.isArray(candidates) ? candidates : [];
20|	return [...list].sort((a, b) => compareCentralQueueCandidates(a, b, policy));
21|}

