1|import { resolveStagesForTask, candidateStageIndex } from "../stageResolution.js";
2|import { isSchedulerRunnable } from "../scheduler/isSchedulerRunnable.js";
3|import { sortCentralQueue } from "../scheduler/sortCentralQueue.js";
4|import { taskRequirements } from "./taskRequirements.js";
5|
6|/***
7| * MARK: scanClaimableTasks
8| * @description Scans all projects for tasks a Runner may claim, mirroring
9| *   the embedded scheduler's scan (`findNextCandidateTask`): status
10| *   in_stage, resolvable stages, on-stage index, runnable, unblocked, and
11| *   — crucially — not already lease-held (the claim fence stays the
12| *   single arbiter; the scan only avoids wasted attempts). Results are
13| *   sorted through the SAME central-queue seam as the scheduler and the
14| *   queue display (`sortCentralQueue`), so backend-routed and embedded
15| *   dispatch always prioritize identically: default "oldest-first" — the
16| *   oldest waiting task first, wherever it lives, with furthest-along-as-a-
17| *   percentage as tiebreak — plus the starvation ceiling (`maxWaitMs`):
18| *   candidates waiting past it jump ahead oldest-first. The ceiling comes
19| *   from `maxWaitMs` when given, else config `dispatchMaxWaitMs`, else the
20| *   built-in 15-minute default in oldest-first mode (task 16d6fbd6).
21| *   Human/non-model stages are excluded here (their requirements mark
22| *   `runnableType: false`).
23| * @example scanClaimableTasks({ projectStore, taskStore, claimStore }) => [{ projectId, taskId, task, req }]
24| * @param {Object} deps - Stores (`projectStore`, `taskStore`, `claimStore`).
25| * @param {Object} [opts] - `{ projectIds }` (Runner-enforced allowlist), `{ maxWaitMs, now, order }` (central-queue policy overrides; omitted = config defaults).
26| * @returns {Array} Claimable tasks with requirements, in dispatch order.
27| ***/
28|export function scanClaimableTasks(deps = {}, opts = {}) {
29|	const { projectStore, taskStore, claimStore } = deps;
30|	const only = Array.isArray(opts.projectIds) ? new Set(opts.projectIds) : null;
31|	if (!projectStore || typeof projectStore.listProjects !== "function") return [];
32|	if (!taskStore || typeof taskStore.listTasks !== "function") return [];
33|	const out = [];
34|	for (const project of projectStore.listProjects()) {
35|		if (only && !only.has(project.id)) continue;
36|		let tasks = [];
37|		try {
38|			tasks = taskStore.listTasks(project.id, project.cwd) || [];
39|		} catch {
40|			continue;
41|		}
42|		for (const task of tasks) {
43|			if (!task || task.status !== "in_stage") continue;
44|			if (claimStore && typeof claimStore.describe === "function" && claimStore.describe(task.id)) {
45|				continue;
46|			}
47|			let blockCheck = { blocked: false };
48|			try {
49|				blockCheck = taskStore.isTaskBlocked(project.id, task.id);
50|			} catch {
51|				continue;
52|			}
53|			const stages = resolveStagesForTask(project, task);
54|			if (!Array.isArray(stages) || stages.length === 0) continue;
55|			const stageIndex = candidateStageIndex(stages, task.currentStageId);
56|			if (stageIndex === -1) continue;
57|			const stage = stages[stageIndex];
58|			if (
59|				!isSchedulerRunnable(task, stage, {
60|					blocked: blockCheck.blocked,
61|					claimed: false,
62|				})
63|			) {
64|				continue;
65|			}
66|			// The task's own pipeline stages (resolved above) travel into
67|			// requirements, so a task on any pipeline is judged by its own
68|			// stage — never the viewed pipeline's mirror.
69|			const req = taskRequirements(project, task, stages);
70|			if (!req.runnableType) continue;
71|			const enteredAt = new Date(task.enteredStageAt || task.updatedAt || 0).getTime();
72|			out.push({
73|				projectId: project.id,
74|				taskId: task.id,
75|				task,
76|				stage,
77|				req,
78|				stageIndex,
79|				totalStages: stages.length,
80|				enteredStageAt: Number.isFinite(enteredAt) ? enteredAt : 0,
81|			});
82|		}
83|	}
84|	// Central-queue order, shared with the embedded scheduler and the queue
85|	// display: overdue (past the ceiling) first oldest-first, then the
86|	// configured mode — default oldest-waiting-first with furthest-along
87|	// percentage as tiebreak.
88|	return sortCentralQueue(out, opts);
89|}

